    const int Lives = 0x27D8, EnergyOff = 0x27D6, ScoreLo = 0x6C0E, ScoreHi = 0x6C10, HurtCooldown = 0x6BC9, Collected = 0x2A76, RngBase = 0x2CEC;
    const int Terrain = 0x9107, TerrainStride = 0xF, BurstLo = 0x50A8, BurstHi = 0x52E8;

    static string Hex(byte[] b) => Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();

    static List<(string Keys, List<string> Actions)> Expand((string Keys, int Ticks)[] script)
    {
        var list = new List<(string, List<string>)>();
        var pending = new List<string>();
        foreach (var (keys, n) in script)
        {
            if (keys.StartsWith('@') || keys.StartsWith('=')) { pending.Add(keys); continue; }
            for (int i = 0; i < n; i++) { list.Add((keys, pending)); pending = new List<string>(); }
        }
        return list;
    }

    static void Apply(LevelScene scene, string action)
    {
        if (action[0] == '@')
        {
            string[] xy = action[1..].Split(',');
            scene.Warp(int.Parse(xy[0]), int.Parse(xy[1]));
            return;
        }
        string[] kv = action[1..].Split(':');
        switch (kv[0])
        {
            case "lives": scene.State.Wb(Lives, int.Parse(kv[1])); break;
            case "energy": scene.State.Wb(EnergyOff, int.Parse(kv[1])); break;
            case "club":
            {
                string[] xy = kv[1].Split(',');
                scene.PokeClub(int.Parse(xy[0]), int.Parse(xy[1]));
                break;
            }
            case "rng":
            {
                byte[] b = Convert.FromHexString(kv[1]);
                for (int i = 0; i < b.Length; i++) scene.State.Wb(RngBase + i, b[i]);
                break;
            }
            default: throw new InvalidOperationException($"unknown poke '{action}'");
        }
    }

    static string PlatformText(LevelState s)
    {
        var l = new List<string>();
        for (int i = 0; i < 16; i++)
        {
            int b = Terrain + i * TerrainStride, sp = s.Rw(b + 4);
            if (sp != 0xFFFF) l.Add($"{i}/{s.Rw(b)}/{s.Rw(b + 2)}/{sp:X4}");
        }
        return l.Count == 0 ? "-" : string.Join(",", l);
    }

    static string StateText(LevelState s)
    {
        int bursts = 0;
        for (int b = BurstLo; b < BurstHi; b += 0x12) if (s.Rw(b + 4) != 0xFFFF) bursts++;
        string rng = string.Join(",", Enumerable.Range(0, 5).Select(i => s.Rb(RngBase + i).ToString("x2")));
        long score = (long)(s.Rw(ScoreLo) & 0xFFFF) | ((long)(s.Rw(ScoreHi) & 0xFFFF) << 16);
        return $"{score}:{s.Rb(EnergyOff)}:{s.Rb(Lives)}:{s.Rb(HurtCooldown)}:{s.Rw(Off.PlayerX)}:{s.Rw(Off.PlayerY)}:{s.Rw(Collected)}:{PlatformText(s)}:{bursts}:{rng}";
    }

    public static int Run(string bootPath, string originalDir, int level, int ticks, string[] refLines)
    {
        Pre2Port.Recovered.ForegroundTiles.Disabled = true;   // the Python reference renders no foreground layer (asm 3721, verified separately by fgdump / work/fg_cross.py): compare the frames without it
        var byScenario = new Dictionary<string, List<string[]>>();
        foreach (string raw in refLines)
        {
            string[] p = raw.Trim().Split(':');
            if (p.Length < 15 || (p[0] != $"B{level}" && p[0] != $"PL{level}")) continue;
            if (!byScenario.TryGetValue(p[1], out var l)) byScenario[p[1]] = l = new List<string[]>();
            l.Add(p);
        }
        if (byScenario.Count == 0)
        {
            Console.WriteLine($"level: no bonus / platform reference lines for B{level} / PL{level}");
            return 1;
        }

        byte[] boot = BootImage.Load(bootPath);
        int pass = 0, fail = 0;
        foreach (var (name, lines) in byScenario)
        {
            if (!Scenarios.TryGetValue(name, out var script))
            {
                Console.WriteLine($"FAIL {lines[0][0]} {name}: unknown scenario (no input script)");
                fail++;
                continue;
            }
            var scene = new LevelScene(boot, originalDir, level, hud: false, player: true, objects: true, damage: false, bonus: true, platforms: true);
            var fb = new Framebuffer();
            var input = new Input();
            var want = lines.ToDictionary(p => int.Parse(p[2]));
            var plan = Expand(script);
            int scPass = 0, scFail = 0, maxScore = 0, maxCollected = 0;
            int lastLives = -1, lastEnergy = -1;
            for (int t = 0; t < Math.Min(plan.Count, ticks); t++)
            {
                var (keys, actions) = plan[t];
                string err = "";
                try
                {
                    foreach (string a in actions) Apply(scene, a);
                    input.Set(Input.Key.Left, keys.Contains('L'), false);
                    input.Set(Input.Key.Right, keys.Contains('R'), false);
                    input.Set(Input.Key.Up, keys.Contains('U'), false);
                    input.Set(Input.Key.Down, keys.Contains('D'), false);
                    scene.Update(input);
                    scene.Draw(fb);
                }
                catch (ObjectGapException e) { err = e.Message; }
                catch (NotSupportedException e) { err = e.Message; }
                if (err != "")
                {
                    Console.WriteLine($"FAIL {lines[0][0]} {name} tick {t}: gap: {err}");
                    scFail++;
                    break;
                }
                LevelState s = scene.State;
                maxScore = Math.Max(maxScore, (int)((long)(s.Rw(ScoreLo) & 0xFFFF) | ((long)(s.Rw(ScoreHi) & 0xFFFF) << 16)));
                maxCollected = Math.Max(maxCollected, s.Rw(Collected));
                lastLives = s.Rb(Lives); lastEnergy = s.Rb(EnergyOff);
                if (!want.TryGetValue(t, out var w)) continue;
                var pal = new byte[16 * 3];
                for (int i = 0; i < 16; i++) { pal[i * 3] = fb.Palette[i].R; pal[i * 3 + 1] = fb.Palette[i].G; pal[i * 3 + 2] = fb.Palette[i].B; }
                string got = StateText(s);
                string exp = string.Join(":", w[3..13]);
                string gotFb = Hex(fb.Pixels), gotPal = Hex(pal);
                bool stateOk = got == exp, fbOk = gotFb == w[13] && gotPal == w[14];
                if (Environment.GetEnvironmentVariable("PRE2_CAMT") is string ct && ct.Split(',')[0] == name && t >= int.Parse(ct.Split(',')[1]) && t <= int.Parse(ct.Split(',')[2])) Console.WriteLine($"CAM t{t} col={s.Rw(Off.CamCol)} row={s.Rw(Off.CamRow)} px={s.Rw(0x4F1C)} py={s.Rw(0x4F1E)}"); if (Environment.GetEnvironmentVariable("PRE2_CAMT") is string ct2 && ct2.Split(',').Length > 3 && ct2.Split(',')[0] == name && t >= int.Parse(ct2.Split(',')[1]) && t <= int.Parse(ct2.Split(',')[2])) for (int o = 0x5720; o >= 0x4F0A; o -= 0x12) if (s.Rw(o + 4) != 0xFFFF) Console.WriteLine($"   s{t} {o:X4} " + string.Join(" ", Enumerable.Range(0, 9).Select(w => s.Rw(o + w * 2).ToString("X4"))));   // debug
                if (Environment.GetEnvironmentVariable("PRE2_DSDUMP") is string dd && dd.Split(',')[0] == name && int.Parse(dd.Split(',')[1]) == t) { var dsb = new byte[0x10000]; for (int q = 0; q < 0x10000; q++) dsb[q] = (byte)s.Rb(q); File.WriteAllBytes(dd.Split(',')[2], dsb); }   // debug: DS image of the tick
                if (stateOk && fbOk) { scPass++; continue; }
                scFail++;
                string[] g = got.Split(':'), e2 = exp.Split(':');
                string[] names = { "score", "energy", "lives", "hurt", "px", "py", "collected", "platforms", "bursts", "rng" };
                int di = Enumerable.Range(0, Math.Min(g.Length, e2.Length)).FirstOrDefault(i => g[i] != e2[i]);
                if (!fbOk && Environment.GetEnvironmentVariable("PRE2_FBDUMP") is string dumpDir) File.WriteAllBytes(Path.Combine(dumpDir, $"cs_{name}_{t}.bin"), fb.Pixels);
                if (!fbOk && Environment.GetEnvironmentVariable("PRE2_SLOTS") == "1")   // debug: active sprite records 0x5720 down to 0x4F0A (the 26FA order) of the failing tick
                    for (int o = 0x5720; o >= 0x4F0A; o -= 0x12) if (s.Rw(o + 4) != 0xFFFF) Console.WriteLine($"   t{t} {o:X4} id={s.Rw(o + 4):X4} x={(short)s.Rw(o)} y={(short)s.Rw(o + 2)} raw=" + string.Join(" ", Enumerable.Range(0, 9).Select(w => s.Rw(o + w * 2).ToString("X4"))));
                string what = stateOk ? "ok" : $"{names[Math.Min(di, names.Length - 1)]} got={g[di]} want={e2[di]}";
                Console.WriteLine($"FAIL {lines[0][0]} {name} tick {t} keys={keys}: state {what} fb {(fbOk ? "ok" : $"got={gotFb[..8]}/{gotPal[..8]} want={w[13][..8]}/{w[14][..8]}")}");
                if (scFail >= (int.TryParse(Environment.GetEnvironmentVariable("PRE2_MAXFAIL"), out var mf) ? mf : 5)) { Console.WriteLine($"  ... {name}: stopping after {scFail} failures"); break; }   // PRE2_MAXFAIL=n: debug, keep comparing past the 5th failure
            }
            Console.WriteLine($"{(scFail == 0 && scPass > 0 ? "PASS" : "FAIL")} {lines[0][0]} {name}: {scPass} ticks ok, {scFail} failed (of {Math.Min(plan.Count, ticks)}; ref has {lines.Count}); max score {maxScore}, cells collected {maxCollected}, end lives {lastLives} energy {lastEnergy}");
            pass += scPass; fail += scFail;
            if (scPass == 0 && scFail == 0) fail++;
        }
        Console.WriteLine($"level: {pass} PASS, {fail} FAIL");
        return fail == 0 && pass > 0 ? 0 : 1;
    }
}
